80	        let f = self.frontiers.insert(frontier).expect("invariant");
81	
82	        // Notify interested nodes about new frontier
83	        if self.graph.is_source(node) {
84	            for n in &self.graph {
85	                let options = self.graph[n].options();
86	                if options.interests.contains(&Interest::Enter) {
87	                    self.events[n].push_back(Event::Insert(key.clone()));
88	                }
89	            }
90	        }
91	
92	        // Consume current node, and return frontier identifier
93	        let frontier = &mut self.frontiers[f];
94	        frontier.take().expect("invariant");
95	        f
96	    }
