38	/// Attempt conversion to [`Selector`].
39	///
40	/// This trait allows to convert an arbitrary value to a selector, using a
41	/// [`Cow`] smart pointer to avoid unnecessary cloning, e.g. for references.
42	pub trait TryToSelector {
43	    /// Attempts to convert to a selector.
44	    ///
45	    /// # Errors
46	    ///
47	    /// In case conversion fails, an error should be returned.
48	    fn try_to_selector(&self) -> Result<Cow<'_, Selector>>;
49	}
50	
51	// ----------------------------------------------------------------------------
52	// Trait implementations
53	// ----------------------------------------------------------------------------
54	
55	impl TryToSelector for Selector {
56	    /// Attempts to convert to a selector.
57	    #[inline]
58	    fn try_to_selector(&self) -> Result<Cow<'_, Selector>> {
59	        Ok(Cow::Borrowed(self))
60	    }
61	}
62	
63	impl TryToSelector for &Selector {
64	    /// Attempts to convert to a selector.
65	    #[inline]
66	    fn try_to_selector(&self) -> Result<Cow<'_, Selector>> {
67	        TryToSelector::try_to_selector(*self)
68	    }
69	}
70	
71	// ----------------------------------------------------------------------------
72	
73	impl TryToSelector for Id {
74	    /// Attempts to convert to a selector.
75	    ///
76	    /// Since all identifiers are also valid selectors, implementing this trait
77	    /// ensures we can also pass identifier references to [`Builder::add`][].
78	    ///
79	    /// [`Builder::add`]: crate::id::matcher::Builder::add
80	    ///
81	    /// # Examples
82	    ///
83	    /// ```
84	    /// # use std::error::Error;
85	    /// # fn main() -> Result<(), Box<dyn Error>> {
86	    /// use zrx_id::{Id, Selector, TryToSelector};
87	    ///
88	    /// // Create selector from identifier
89	    /// let id: Id = "zri:file:::docs:index.md:".parse()?;
90	    /// let selector = id.try_to_selector()?;
91	    /// # Ok(())
92	    /// # }
93	    /// ```
94	    #[inline]
95	    fn try_to_selector(&self) -> Result<Cow<'_, Selector>> {
96	        self.to_owned().try_into().map(Cow::Owned)
97	    }
98	}
99	
100	impl TryToSelector for &Id {
101	    /// Attempts to convert to a selector.
102	    #[inline]
103	    fn try_to_selector(&self) -> Result<Cow<'_, Selector>> {
104	        TryToSelector::try_to_selector(*self)
105	    }
106	}
