109	// Blanket implementations
110	// ----------------------------------------------------------------------------
111	
112	impl<T> TryToSelector for T
113	where
114	    T: AsRef<str>,
115	{
116	    /// Attempts to convert to a selector.
117	    ///
118	    /// # Errors
119	    ///
120	    /// Returns [`Error::Prefix`][] if the prefix isn't `zrs`. Low-level format
121	    /// errors are returned as part of [`Error::Format`][].
122	    ///
123	    /// [`Error::Format`]: crate::id::Error::Format
124	    /// [`Error::Prefix`]: crate::id::Error::Prefix
125	    ///
126	    /// # Examples
127	    ///
128	    /// ```
129	    /// # use std::error::Error;
130	    /// # fn main() -> Result<(), Box<dyn Error>> {
131	    /// use zrx_id::{Selector, TryToSelector};
132	    ///
133	    /// // Create selector from string
134	    /// let selector = "zrs:::::**/*.md:".try_to_selector()?;
135	    /// # Ok(())
136	    /// # }
137	    /// ```
138	    #[inline]
139	    fn try_to_selector(&self) -> Result<Cow<'_, Selector>> {
140	        self.as_ref().parse().map(Cow::Owned)
141	    }
142	}
